sys_script_client.script:
function onLoad() {
    //we need a condition, otherwise this is a simple onload type of client script. 
    //Condition: if the device name is empty, dont show the device details, delivery details, otherwise , show all.
    if (g_form.getValue('u_reference_2') == '') {
        g_form.setSectionDisplay('device_details', false);
        g_form.setSectionDisplay('delivery_details', false);
	}else{
    g_form.getReference('u_reference_2',getDetails); 
    	function getDetails(details){
        g_form.setValue('u_string_3', details.model_number);
        g_form.setValue('u_string_4', details.short_description);
        g_form.setValue('u_price_5', details.u_price_2);
        g_form.setValue('u_glide_date_7', details.warranty_expiration);
    }
    }
}
